from playwright.sync_api import sync_playwright
from h import *
import json,zipfile,io
import os
if not os.path.exists('big.png'):
    from PIL import Image
    Image.frombytes('RGB',(2000,2000),os.urandom(2000*2000*3)).save('big.png')  # ensure_big: incompressible 2000x2000 test image
CONTENT="(()=>{const p=PV.S.project;return JSON.stringify({person:p.person,socials:p.socials,secs:p.sections.map(s=>({id:s.id,t:s.type,title:s.title,data:s.data,items:s.items,vis:s.visible}))})})()"
with sync_playwright() as p:
    b=p.chromium.launch(); ctx=b.new_context(viewport={'width':1600,'height':900},accept_downloads=True); pg=ctx.new_page()
    errs=[]; pg.on('pageerror',lambda e:errs.append(str(e)))
    to_editor(pg, 1, 'Professional', 'E2E')
    content0=pg.evaluate(CONTENT); design0=pg.evaluate('JSON.stringify(PV.S.project.design)')
    pg.click('.miybtn'); pg.wait_for_timeout(300)
    pg.click('.preset:has-text("More Futuristic")'); pg.wait_for_timeout(1200)
    nv=pg.evaluate('PV.S.variations.length'); ok('MIY generates 3 variations', nv==3, nv)
    ok('variation previewed live', pg.evaluate('PV.S.activeVar')!=None and 't-' in fr(pg).locator('.pv').get_attribute('class') and fr(pg).locator('.pv').get_attribute('class')!='pv t-professional', fr(pg).locator('.pv').get_attribute('class'))
    ok('original design untouched while previewing', pg.evaluate('JSON.stringify(PV.S.project.design)')==design0)
    ok('content untouched by variation', pg.evaluate(CONTENT)==content0)
    sigs=pg.evaluate('PV.S.variations.map(v=>v.design.template+v.design.palette.accent+v.design.layout.hero)'); ok('variations are distinct', len(set(sigs))==3, sigs)
    ok('variation thumbs render', pg.locator('.vcard .tf iframe').count()==4)
    pg.click('.miy-actions [data-act=miycompare]'); pg.wait_for_timeout(1200)
    ok('compare shows two frames', pg.locator('.pv-cmp iframe').count()==2)
    pg.screenshot(path='compare.png')
    pg.click('.miy-actions [data-act=miycompare]'); pg.wait_for_timeout(400)
    pg.click('.vcard:nth-child(3)'); pg.wait_for_timeout(500)
    pg.click('.miy-actions [data-act=miyapply]'); pg.wait_for_timeout(800)
    ok('apply changes design', pg.evaluate('JSON.stringify(PV.S.project.design)')!=design0)
    ok('apply keeps content', pg.evaluate(CONTENT)==content0)
    pg.click('.appbar [data-act=undo]'); pg.wait_for_timeout(600)
    ok('undo restores original design', pg.evaluate('JSON.stringify(PV.S.project.design)')==design0)
    pg.click('.miybtn'); pg.fill('#miy-text','futuristic digital playground with bold typography, neon accents, asymmetric project cards and smooth scroll animations'); pg.click('[data-act=miycustom]'); pg.wait_for_timeout(900)
    ok('custom text -> 3 variations + interpretation', pg.evaluate('PV.S.variations.length')==3 and len(pg.evaluate('PV.S.interpreted'))>=4, pg.evaluate('PV.S.interpreted'))
    pg.click('.miy-actions [data-act=miydiscard]'); pg.wait_for_timeout(500)
    ok('discard returns to current design', pg.evaluate('PV.S.variations.length')==0 and pg.evaluate('JSON.stringify(PV.S.project.design)')==design0)
    pg.fill('#miy-text','zzz qqq xxx'); pg.click('[data-act=miycustom]'); pg.wait_for_timeout(500)
    ok('unsupported request explains + offers presets', pg.is_visible('.notice.warn') and pg.locator('.notice.warn .seg').count()>=3)
    pg.evaluate("PV.ACT.tplpick({dataset:{id:'digital-playground'}})"); pg.wait_for_timeout(600)
    ok('template switch (minimal->maximal) keeps content', pg.evaluate(CONTENT)==content0 and pg.evaluate('PV.S.project.design.system')=='maximal')
    pg.evaluate("PV.ACT.tplpick({dataset:{id:'professional'}})"); pg.wait_for_timeout(300)
    # avatar upload
    pg.evaluate("PV.ACT.openpanel({dataset:{p:'content'}})"); pg.wait_for_timeout(300)
    pg.evaluate("PV.S.ui.openGroup.person=true"); pg.evaluate("PV.ACT.openpanel({dataset:{p:'content'}})"); pg.wait_for_timeout(300)
    pg.click('#wspanel [data-act=upload][data-path="person/avatar"]') if pg.locator('#wspanel [data-act=upload][data-path="person/avatar"]').count() else None
    pg.set_input_files('#fileIn','big.png'); pg.wait_for_timeout(2500)
    av=pg.evaluate('PV.S.project.person.avatar'); ok('upload stored as asset reference', av.startswith('asset:'), av)
    sz=pg.evaluate('(()=>{const a=Object.values(PV.S.project.assets)[0];return a?a.size:-1})()'); ok('large image downscaled (<1MB from 12MB)', 0<sz<1000000, sz)
    ok('avatar visible in preview', fr(pg).locator('img.avatar').count()==1 and fr(pg).locator('img.avatar').get_attribute('src').startswith('data:image'))
    # code editor
    pg.click('.nextbtn'); pg.wait_for_timeout(1500)
    ok('code route', pg.evaluate('location.hash')=='#/editor/code')
    pg.click('.codecol .tab:has-text("CSS")'); pg.wait_for_timeout(300)
    css=pg.input_value('#codearea'); ok('css tab shows real generated css', ':root{--c-primary' in css and len(css)>10000)
    pg.fill('#codearea', css+'\n.name{color:rgb(255,0,0)!important}\n'); pg.wait_for_timeout(1800)
    col=fr(pg).locator('.name').evaluate('e=>getComputedStyle(e).color'); ok('manual CSS appears in preview', col=='rgb(255, 0, 0)', col)
    ok('manual badge shown', pg.locator('.codecol .tab .dot').count()>=1)
    pg.click('.codecol .tab:has-text("JavaScript")'); pg.wait_for_timeout(300)
    js=pg.input_value('#codearea'); pg.fill('#codearea', js+"\ntry{parent.document.title}catch(e){document.body.setAttribute('data-iso','blocked')}\ntry{localStorage.getItem('x')}catch(e){document.body.setAttribute('data-ls','blocked')}\ndocument.body.setAttribute('data-custom','ran');\n"); pg.wait_for_timeout(1800)
    bd=fr(pg).locator('body'); ok('custom JS ran in preview', bd.get_attribute('data-custom')=='ran')
    ok('custom JS cannot touch parent app (sandbox)', bd.get_attribute('data-iso')=='blocked' and bd.get_attribute('data-ls')=='blocked', [bd.get_attribute('data-iso'),bd.get_attribute('data-ls')])
    pg.click('.codecol .tab:has-text("HTML")'); pg.wait_for_timeout(300)
    h=pg.input_value('#codearea'); pg.fill('#codearea', h.replace('</main>','<section id="hand" class="sec"><div class="wrap"><h2>Hand-written block</h2></div></section>\n</main>')); pg.wait_for_timeout(1800)
    ok('manual HTML appears in preview', fr(pg).locator('#hand h2').count()==1)
    pg.uncheck('#livechk'); pg.fill('#codearea', pg.input_value('#codearea')+'\n<!-- draft -->'); pg.wait_for_timeout(200)
    ok('draft pending flagged', pg.evaluate('PV.S.codeDraft.dirty')==True)
    pg.click('.appbar .back'); pg.wait_for_timeout(1500)
    ok('leaving with unapplied code asks first', pg.is_visible('.dlg-wrap') and pg.evaluate('!!document.querySelector("#codehost")'))
    pg.click('.dlg-wrap [data-dlg=no]'); pg.wait_for_timeout(300); ok('stay keeps screen + draft', pg.evaluate('location.hash')=='#/editor/code' and pg.evaluate('PV.S.codeDraft.dirty'))
    pg.click('[data-act=codeapply]'); pg.wait_for_timeout(500); ok('apply clears draft', pg.evaluate('PV.S.codeDraft.dirty')==False)
    pg.fill('#codearea', pg.input_value('#codearea')+'<!-- again -->'); pg.wait_for_timeout(200)
    pg.evaluate('history.back()'); pg.wait_for_timeout(900)
    ok('browser Back also guarded', pg.is_visible('.dlg-wrap'))
    pg.click('.dlg-wrap [data-dlg=no]'); pg.wait_for_timeout(900)
    ok('browser Back cancelled -> still on code', pg.evaluate('location.hash')=='#/editor/code', pg.evaluate('location.hash'))
    pg.click('[data-act=codeapply]'); pg.wait_for_timeout(400)
    pg.click('.nextbtn'); pg.wait_for_timeout(800); ok('export route', pg.evaluate('location.hash')=='#/editor/export')
    pg.evaluate("PV.commit('t',p=>{p.sections.find(s=>s.type=='education').visible=false;p.sections.push({id:'sEmpty',type:'publications',title:'Publications',visible:true,nav:true,data:{},items:[],style:{}});},{structural:true})"); pg.wait_for_timeout(900); pg.reload(); pg.wait_for_timeout(1200)
    ok('export screen lists included/excluded', pg.locator('.inc:not(.check) .out').count()>=2 and 'Experience' in pg.inner_text('.inc:not(.check)'))
    dep=pg.locator('.card-a:has-text("What this file depends on") .status'); ok('dependency report honest (fonts remote)', 'not fully self-contained' in dep.inner_text(), dep.inner_text())
    with pg.expect_download() as dl: pg.click('[data-act=dlhtml]')
    html=open(dl.value.path(),encoding='utf8').read(); dl.value.save_as('out.html')
    ok('download is a complete HTML doc', html.startswith('<!DOCTYPE html>') and '<meta property="og:title"' in html and 'application/ld+json' in html and 'rel="icon"' in html)
    ok('export contains current content + manual edits', 'Hand-written block' in html and 'rgb(255,0,0)' in html and 'Aryan Singh' in html)
    ok('export embeds uploaded image', 'src="data:image/' in html)
    ok('export has no builder bridge', '__PV' not in html and 'pv-sel' not in html and 'data-pv=' not in html)
    ok('enabled sections included', 'Kisan Labs' in html and 'Mandi Mitra' in html)
    pg.goto(APP+'#/editor/code'); pg.wait_for_timeout(1500)
    pg.click('.codecol .tab:has-text("HTML")'); pg.click('[data-act=coderestore][data-t=html]'); pg.wait_for_timeout(400); ok('restore asks for confirmation', pg.is_visible('.dlg-wrap')); pg.click('.dlg-wrap [data-dlg=yes]'); pg.wait_for_timeout(1200)
    ok('restore generated HTML', pg.evaluate('PV.S.project.code.html')==None and pg.evaluate('PV.S.project.code.css')!=None)
    pg.goto(APP+'#/editor/export'); pg.wait_for_timeout(1500)
    with pg.expect_download() as dl2: pg.click('[data-act=dlhtml]')
    html2=open(dl2.value.path(),encoding='utf8').read()
    ok('after restore: disabled/empty sections excluded', 'Savitribai Phule' not in html2 and 'id="sec-sEmpty"' not in html2 and 'Hand-written block' not in html2 and 'rgb(255,0,0)' in html2)
    ok('after restore: enabled sections present', 'Kisan Labs' in html2 and 'Mandi Mitra' in html2)
    with pg.expect_download() as dz: pg.click('[data-act=dlzip]')
    z=zipfile.ZipFile(dz.value.path()); names=z.namelist(); idx=z.read('index.html').decode()
    ok('zip valid; has index.html + assets/ + README', 'index.html' in names and any(n.startswith('assets/') for n in names) and z.testzip() is None, names)
    ok('zip html references asset files, not data URLs', 'assets/' in idx and 'src="data:image' not in idx)
    pg2=ctx.new_page(); e2=[]; pg2.on('pageerror',lambda e:e2.append(str(e))); pg2.set_viewport_size({'width':390,'height':800})
    pg2.goto(OUTHTML); pg2.wait_for_timeout(1500)
    ok('exported site runs standalone (custom JS too)', pg2.get_attribute('body','data-custom')=='ran' and not e2, e2)
    ok('mobile: no horizontal overflow', pg2.evaluate('document.documentElement.scrollWidth')<=391, pg2.evaluate('document.documentElement.scrollWidth'))
    pg2.click('.nav-toggle'); pg2.wait_for_timeout(300); ok('mobile nav toggle opens menu', pg2.is_visible('.nav-links a >> nth=0'))
    pg2.screenshot(path='exp_mobile.png')
    with pg.expect_download() as dj: pg.click('[data-act=dljson]')
    raw=open(dj.value.path()).read(); jd=json.loads(raw); ok('json has sections/design/code', 'design' in jd and jd['code']['css'] is not None)
    open('proj.json','w').write(raw)
    pg.goto(APP+'#/projects'); pg.wait_for_timeout(1000); pg.reload(); pg.wait_for_timeout(800)
    n0=pg.evaluate('PV.S.index.length'); pg.set_input_files('#jsonIn','proj.json'); pg.wait_for_timeout(1000)
    ok('JSON import creates project', pg.evaluate('PV.S.index.length')==n0+1, [n0,pg.evaluate('PV.S.index.length')])
    pg.set_input_files('#jsonIn',{'name':'bad.json','mimeType':'application/json','buffer':b'{"hello":1}'}); pg.wait_for_timeout(600); ok('bad import rejected safely', pg.evaluate('PV.S.index.length')==n0+1)
    print('errs',errs); b.close()
